using UnityEngine;
namespace Kamilunavo.RisingSteps.Core
{
 public static class RisingCampaign
 {
  public const int LevelsPerRealm=10,RealmCount=10,LevelCount=LevelsPerRealm*RealmCount;
  static readonly string[][] De={new[]{"Erste Blüten","Wolkenkurve","Gänseblümchenweg","Windwiese","Himmelsbogen","Blütenzickzack","Sonnenlichtung","Weite Wiesen","Wolkenkrone","Gipfelgarten"},new[]{"Am Quellbecken","Wasserstufen","Zwischen Kaskaden","Schilfbogen","Blaue Lagune","Über den Strom","Sprühnebelpfad","Die langen Fälle","Kristallbecken","Krone der Quellen"},new[]{"Tor der Alten","Sandsteinstufen","Säulengasse","Goldene Kurve","Mosaikpfad","Über die Ruinen","Sonnenarkaden","Die hohen Tore","Tempelkrone","Zum Himmelslicht"},new[]{"Unter dem Blätterdach","Lianenbogen","Grüne Schlucht","Orchideenpfad","Durch die Baumkronen","Auf den Wurzeln","Nebellichtung","Die großen Farne","Urwaldkrone","Zum Sonnenbaum"},new[]{"Am Kristalltor","Prismastufen","Blaue Grotte","Gläserne Kurve","Zwischen Splittern","Lichtbrücken","Amethystpfad","Die stillen Spitzen","Prismenkrone","Das helle Herz"},new[]{"Erster Schnee","Eiswind","Froststufen","Über die Spalte","Weiße Kurve","Nordlichtpfad","Schneekristalle","Die hohen Gletscher","Frostkrone","Zum Nordlicht"},new[]{"Oasenblick","Dünenstufen","Palmenbogen","Sandsteinpfad","Über die Dünen","Goldene Brücke","Am Felsentor","Die langen Schatten","Wüstenkrone","Oase im Himmel"},new[]{"Warmer Stein","Aschestufen","Glutbogen","Über die Schlacke","Basaltkurve","Zwischen Kratern","Lavaferne","Die hohen Schlote","Feuerkrone","Zum Glutportal"},new[]{"Am Korallenstrand","Muschelstufen","Küstenbogen","Über das Blau","Leuchtturmpfad","Zwischen Segeln","Gezeitenbrücke","Die hohen Klippen","Meereskrone","Hafen der Wolken"},new[]{"Erstes Sternlicht","Mondstufen","Nachtbogen","Sternenpfad","Über die Sichel","Zwischen Laternen","Lichtspuren","Die stillen Höhen","Sternenkrone","Zum Morgenstern"}};
  static readonly string[][] En={new[]{"First Flowers","Cloud Curve","Daisy Trail","Wind Meadow","Sky Arc","Flower Zigzag","Sunny Clearing","Wide Meadows","Cloud Crown","Summit Garden"},new[]{"Spring Pool","Water Steps","Between Cascades","Reed Arc","Blue Lagoon","Across the Stream","Mist Trail","The Long Falls","Crystal Pools","Crown of Springs"},new[]{"Ancient Gate","Sandstone Steps","Pillar Walk","Golden Curve","Mosaic Trail","Across the Ruins","Sun Arcades","The High Gates","Temple Crown","Into the Sky Light"},new[]{"Under the Canopy","Vine Arc","Green Gorge","Orchid Trail","Through the Treetops","Along the Roots","Mist Clearing","The Great Ferns","Jungle Crown","To the Sun Tree"},new[]{"Crystal Gate","Prism Steps","Blue Grotto","Glass Curve","Between Shards","Light Bridges","Amethyst Trail","The Silent Spires","Prism Crown","The Bright Heart"},new[]{"First Snow","Ice Wind","Frost Steps","Across the Crevasse","White Curve","Aurora Trail","Snow Crystals","The High Glaciers","Frost Crown","To the Northern Lights"},new[]{"Oasis View","Dune Steps","Palm Arc","Sandstone Trail","Across the Dunes","Golden Bridge","Rock Gateway","The Long Shadows","Desert Crown","Sky Oasis"},new[]{"Warm Stone","Ash Steps","Ember Arc","Across the Cinders","Basalt Curve","Between Craters","Distant Lava","The High Vents","Fire Crown","To the Ember Portal"},new[]{"Coral Shore","Shell Steps","Coastal Arc","Across the Blue","Lighthouse Trail","Between Sails","Tidal Bridge","The High Cliffs","Ocean Crown","Cloud Harbor"},new[]{"First Starlight","Moon Steps","Night Arc","Star Trail","Across the Crescent","Between Lanterns","Trails of Light","The Silent Heights","Star Crown","To the Morning Star"}};
  public static int LevelId(int realm,int level)=>Mathf.Clamp(realm,0,RealmCount-1)*LevelsPerRealm+Mathf.Clamp(level,0,LevelsPerRealm-1);
  public static string Title(int realm,int level,bool english)=>(english?En:De)[Mathf.Clamp(realm,0,RealmCount-1)][Mathf.Clamp(level,0,LevelsPerRealm-1)];
  public static bool IsUnlocked(RisingProfile p,int realm,int level)=>p!=null&&realm>=0&&realm<RealmCount&&realm<=p.UnlockedRealm&&level>=0&&level<LevelsPerRealm&&(level==0||p.LevelStars!=null&&p.LevelStars.Length==LevelCount&&p.LevelStars[LevelId(realm,level-1)]>0);
  public static int PerfectTarget(int level)=>level==0?0:Mathf.Min(10,3+(level+1)/2);
  public static float TimeTarget(int level)=>180-Mathf.Clamp(level,0,LevelsPerRealm-1)*5;
  public static int Stars(RisingProfile p)=>p.Challenge?(p.Falls>0?1:p.Elapsed<=180?3:2):p.Falls>0?1:p.Elapsed<=TimeTarget(p.Level)&&p.Perfects>=PerfectTarget(p.Level)?3:2;
  public static int RealmStars(RisingProfile p,int realm){int sum=0;for(int i=0;i<LevelsPerRealm;i++)sum+=p.LevelStars[LevelId(realm,i)];return sum;}
 }
}
